async function readBooks() {
  const response = await fetch("/books.json");
  if (!response.ok) throw new Error("Could not load books");
  return response.json();
}
readBooks().then(console.log).catch(console.error);

const controller = new AbortController();
fetch("/books.json", {signal: controller.signal})
  .then(response => response.text()).then(console.log)
  .catch(error => console.log(error.name));
controller.abort();

const params = new URLSearchParams("topic=space&level=1");
params.set("topic", "garden club");
console.log(params.get("topic"));
console.log(params.toString());

try {
  localStorage.setItem("club-books", JSON.stringify(["Moon Trip"]));
  const books = JSON.parse(localStorage.getItem("club-books") || "[]");
  console.log(books.length);
} catch { console.log("Storage is unavailable."); }

if ("geolocation" in navigator) {
  navigator.geolocation.getCurrentPosition(
    position => console.log("Accuracy in metres:", position.coords.accuracy),
    () => console.log("You can choose a place by hand instead."),
    {timeout: 5000}
  );
}

// worker.js
self.onmessage = event => { self.postMessage(event.data * 2); };

// main.js, a separate file on the same local site
const worker = new Worker("./worker.js");
worker.onmessage = event => { console.log(event.data); worker.terminate(); };
worker.postMessage(6);
